        "en": "Every hotel, bakery, cafe, cloud kitchen, and wedding party requires paper napkins by the millions. Using an automatic embossing and folding line, parent tissue reels are continuously embossed with attractive textured patterns, folded, cut, and counted into packs of 100. Production cost per pack of 100 napkins is just ₹14.50, while wholesale to restaurants is ₹22 to ₹26, yielding ₹7.50 to ₹11.50 profit per packet.",
        "ml": "എല്ലാ ഹോട്ടലുകളിലും ബേക്കറികളിലും കല്യാണങ്ങൾക്കും ഏറ്റവും കൂടുതൽ ഉപയോഗിക്കുന്ന ഒന്നാണ് പേപ്പർ നാപ്കിനുകൾ. ഒരു ഓട്ടോമാറ്റിക് മെഷീൻ ഉണ്ടെങ്കിൽ വലിയ പേപ്പർ റോളിൽ നിന്നും മനോഹരമായ ഡിസൈനുകൾ പ്രിന്റ് ചെയ്ത് മിനിറ്റിൽ 1,000 നാപ്കിനുകൾ വരെ നിർമ്മിക്കാം. 100 എണ്ണമുള്ള ഒരു പാക്കറ്റ് നിർമ്മിക്കാൻ വെറും ₹14.50 മാത്രമേ ചെലവ് വരുന്നുള്ളൂ. ഇത് ഹോട്ടലുകൾക്ക് ₹22 മുതൽ ₹26 വരെ വിൽക്കുമ്പോൾ ഒരു പാക്കറ്റിൽ ₹7.50 മുതൽ ₹11.50 വരെ ലാഭം നേടാം.",
        "ar": "تستهلك الفنادق والمقاهي وصالات الأفراح ملايين المناديل الورقية أسبوعياً. بآلة نقش وطي آلية، تتحول رولات الورق الخام إلى مناديل ناعمة ومزخرفة ومطوية بسرعة 1,200 منديل بالدقيقة. تكلفة إنتاج حزمة 100 منديل لا تتجاوز 14.50 روبية، بينما تباع للمطاعم بـ 22 إلى 26 روبية بهامش ربح يفوق 50%."
